import{_ as o,o as c,c as d,a2 as l}from"./chunks/framework.Cv8ZzyHT.js";const u=JSON.parse('{"title":"更新日志","description":"ew-color-picker 各版本的变更记录，含修复、新增与文档修正。","frontmatter":{"title":"更新日志","description":"ew-color-picker 各版本的变更记录，含修复、新增与文档修正。"},"headers":[],"relativePath":"zh/guide/changelog.md","filePath":"zh/guide/changelog.md"}'),a={name:"zh/guide/changelog.md"};function i(r,e,t,h,n,s){return c(),d("div",null,[...e[0]||(e[0]=[l('<h1 id="更新日志" tabindex="-1">更新日志 <a class="header-anchor" href="#更新日志" aria-label="Permalink to &quot;更新日志&quot;">​</a></h1><h2 id="_2-0-4" tabindex="-1">2.0.4 <a class="header-anchor" href="#_2-0-4" aria-label="Permalink to &quot;2.0.4&quot;">​</a></h2><h3 id="新增" tabindex="-1">新增 <a class="header-anchor" href="#新增" aria-label="Permalink to &quot;新增&quot;">​</a></h3><ul><li>新增 <code>@ew-color-picker/select</code> 下拉选择组件与插件：支持自定义选项、占位符、尺寸、键盘操作、外部点击关闭与 ARIA 无障碍规范，可通过 <code>selectClearable</code> 开启清空图标，配置项含 <code>selectItems</code> / <code>selectValue</code> / <code>selectPlaceholder</code> / <code>onSelectChange</code> / <code>onSelectClear</code>，仅在 <code>selectItems</code> 非空时渲染</li><li>新增 <code>@ew-color-picker/gradient</code> 渐变插件：提供可拖拽色标的渐变编辑器，支持线性 / 径向 / 锥形、重复渐变、角度与位置、双位置色标，以及 <code>srgb</code> / <code>srgb-linear</code> / <code>hsl</code> / <code>oklab</code> / <code>oklch</code> 插值提示。CSS 字符串可通过 <code>parseGradient</code> / <code>serializeGradient</code> 稳定回环，默认仅在 <code>showGradient: true</code> 或提供 <code>gradient</code> / <code>gradientStops</code> 时渲染</li><li>新增 <code>@ew-color-picker/checkbox</code> 复选框组件与插件：用主题化方块替代原生复选框外观，底层保留原生 input 以维持语义与键盘操作。插件在提供 <code>checkboxLabel</code> 时渲染到面板底部行，支持 <code>showCheckbox</code> / <code>checkboxChecked</code> / <code>checkboxDisabled</code> / <code>onCheckboxChange</code></li><li>聚合包新增 <code>createEwColorPicker(options)</code> 工厂函数导出，兼容入口包 <code>ew-color-picker</code> 同步支持该导出</li></ul><h3 id="修复" tabindex="-1">修复 <a class="header-anchor" href="#修复" aria-label="Permalink to &quot;修复&quot;">​</a></h3><ul><li>修复 <code>defaultColor</code> 的判断逻辑：此时实例插件尚未创建，改为按静态插件注册表判断 alpha 插件是否已注册；未启用 alpha 时，rgba 格式的默认值正确降级为 hex</li><li>修复无初始颜色或延迟设置颜色时打开面板，色相柱背景、面板光标与色相 / 透明度滑块位置不正确的问题：面板显示后会按当前颜色重新同步定位</li><li>修复色相柱与透明度柱在不同方向组合下面板宽度计算不准确，导致同排元素换行、左右边缘无法对齐的问题</li><li>修复 <code>colorRgbaToHsva</code> 只接受 rgba 字符串的问题，现在兼容 hex / rgb / 颜色关键字等输入</li><li>修复渐变编辑器停靠点行的布局问题：数字输入框数值被裁剪、删除 / 新增按钮被挤到下一行；输入框加宽并压缩步进按钮宽度与行间距后，单行内完整展示</li></ul><h2 id="_2-0-3" tabindex="-1">2.0.3 <a class="header-anchor" href="#_2-0-3" aria-label="Permalink to &quot;2.0.3&quot;">​</a></h2><blockquote><p>本版本已发布到 npm，文档站已同步更新。</p></blockquote><h3 id="新增-1" tabindex="-1">新增 <a class="header-anchor" href="#新增-1" aria-label="Permalink to &quot;新增&quot;">​</a></h3><ul><li>新增 <code>@ew-color-picker/eyedropper</code> 吸管插件：基于浏览器原生 EyeDropper API 从屏幕任意位置取色，自动检测能力，通过 <code>core.setColor()</code> 写回结果，支持 <code>showEyedropper</code> / <code>eyedropperText</code> / <code>onEyedropperPick</code>，用户取消时静默忽略 <code>AbortError</code></li><li>新增 <code>@ew-color-picker/copy-color</code> 复制颜色插件：一键复制当前颜色到剪贴板。按钮底色跟随当前颜色并按对比度自动切换图标颜色，优先使用异步剪贴板 API，失败时降级到 <code>execCommand</code>，复制成功后弹出内置提示气泡，支持 <code>showCopyColor</code> / <code>copyColorText</code> / <code>copiedText</code> / <code>onCopyColor</code></li><li>吸管按钮与复制按钮改为放在颜色值输入框上方的独立工具栏行，不再与输入框、清空 / 确定按钮挤在同一行</li></ul><h3 id="修复-1" tabindex="-1">修复 <a class="header-anchor" href="#修复-1" aria-label="Permalink to &quot;修复&quot;">​</a></h3><ul><li>修复数字输入框步进按钮的上下箭头：补齐图标类名并将尺寸调整为 10px，图标现在完全居中，不再溢出被分割线裁剪</li><li>修复 RGB / HSL 分通道输入框首次点击上下箭头时颜色值被重置为 0 的问题：颜色变化时同步输入框内部值，加减从当前通道值开始计算</li></ul><h2 id="_2-0-2" tabindex="-1">2.0.2 <a class="header-anchor" href="#_2-0-2" aria-label="Permalink to &quot;2.0.2&quot;">​</a></h2><h3 id="修复-2" tabindex="-1">修复 <a class="header-anchor" href="#修复-2" aria-label="Permalink to &quot;修复&quot;">​</a></h3><ul><li>发布产物中的内部依赖改为指向对应版本（<code>^2.0.2</code>），不再沿用旧的 <code>^2.0.0</code> 范围。避免 2.0.1 的插件解析到旧版 <code>@ew-color-picker/utils</code>，导致 <code>getPrefix</code> 不存在而启动报错</li></ul><h2 id="_2-0-1" tabindex="-1">2.0.1 <a class="header-anchor" href="#_2-0-1" aria-label="Permalink to &quot;2.0.1&quot;">​</a></h2><blockquote><p>本版本已发布到 npm，并同步到文档站。</p></blockquote><h3 id="修复-3" tabindex="-1">修复 <a class="header-anchor" href="#修复-3" aria-label="Permalink to &quot;修复&quot;">​</a></h3><ul><li>修复插件开关失效：<code>ewColorPickerPanel: false</code>、<code>ewColorPickerColorMode: false</code>（或对象配置）被默认配置覆盖，实际不生效</li><li>面板容器补充 <code>box-sizing: content-box</code>，不再依赖宿主全局 <code>box-sizing</code> 重置</li><li>移除按视口宽度（<code>max-width: 768px</code>）写死面板、输入框、预设区尺寸的媒体查询，内部尺寸统一由 <code>--panel-width</code> / <code>--panel-height</code> 控制</li><li>预定义色板改为 flex 自动换行，移除硬编码的「每行 10 个」换行规则，修复色块数量与容器宽度不匹配时的错误换行</li><li><code>use()</code> 改为按 <code>pluginName</code> 去重，避免 HMR、重复 import 或多入口场景重复注册同一插件</li><li>插件构造异常改为通过 <code>console.warn</code> 输出插件名与错误信息，不再静默吞掉，便于自定义插件调试</li></ul><h3 id="新增-2" tabindex="-1">新增 <a class="header-anchor" href="#新增-2" aria-label="Permalink to &quot;新增&quot;">​</a></h3><ul><li><code>appendTo</code> 选项：把面板容器挂载到 <code>document.body</code> 或任意容器，避免被弹窗、抽屉、滚动容器的 <code>overflow</code> 裁剪。启用后面板改为相对视口定位，仍按 <code>panelPlacement</code> 计算并做边界翻转，滚动或窗口尺寸变化时自动重算</li><li><code>prefix</code> 选项：自定义全部 CSS 类名前缀（默认 <code>ew-</code>），方便嵌入其他库时避免样式冲突。SCSS 同步提供 <code>$prefix</code> 构建变量，需与 JS 选项保持一致</li><li><code>ApplyOrder</code> 由 <code>const enum</code> 改为普通枚举，可直接从 <code>@ew-color-picker/utils</code> 运行时导入，编写自定义插件时无需手写 <code>&#39;pre&#39;</code> / <code>&#39;post&#39;</code> 字符串</li></ul><h3 id="文档" tabindex="-1">文档 <a class="header-anchor" href="#文档" aria-label="Permalink to &quot;文档&quot;">​</a></h3><ul><li>修正预定义色板、数字输入框的类名，与源码保持一致</li><li>移除不存在的 <code>ewColorPickerBox</code> 嵌套配置写法，统一为顶层选项</li><li>修正 <code>autoPanelPosition</code> 的生效前提说明</li><li>新增 <code>appendTo</code> 选项说明（中英文）</li><li>新增 <code>prefix</code> 选项说明（中英文），含 SCSS 自定义编译示例</li><li>补充 <code>applyOrder</code> 执行顺序说明与用法示例（中英文）</li><li>文档站默认语言改为英文，中文文档迁移到 <code>/zh/</code> 路径，README 默认展示英文版</li></ul><h2 id="_2-0-0" tabindex="-1">2.0.0 <a class="header-anchor" href="#_2-0-0" aria-label="Permalink to &quot;2.0.0&quot;">​</a></h2><p>首个正式发布版本：核心 + 插件架构、14 个包（13 个 scoped 包 + 无 scope 兼容入口包 <code>ew-color-picker</code>）、双语文档站与在线演示。</p>',25)])])}const b=o(a,[["render",i]]);export{u as __pageData,b as default};
